def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

n = int(input())
print("YES" if is_prime(n) else "NO")

def factorial(n):
    if n < 0:
        return -1
    ket_qua = 1
    for i in range(2, n + 1):
        ket_qua *= i
    return ket_qua

n = int(input())
print(factorial(n))

